Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define FOR(a,b,c) for (a=b; a<=c; a++)
#define FORD(a,b,c) for (a=b; a>=c; a--)
#define ADD(a,b) a=((a)+(b))%mod
#define MIN(a,b) (a<b?a:b)
using namespace std;

long long factorial[501],InvFactorial[501],f[501],g[501],h[501][501][2],C[501][501],s,ans,F;
int n,m,mod,Mod,i,j,k,l;

long long qpow(long long a,int b) {
    long long res=1; 
    while (b) {
        if (b&1) res=res*a%mod;
        a=a*a%mod;
        b>>=1;
    }
    return res;
}

int main()
{
    cin >> n >> m >> mod;
    Mod=mod-2;
    factorial[0]=1;
    FOR(i,1,n) factorial[i]=factorial[i-1]*i%mod;
    InvFactorial[n]=qpow(factorial[n],Mod);
    FORD(i,n-1,0) InvFactorial[i]=InvFactorial[i+1]*(i+1)%mod;
    C[0][0]=1;
    FOR(i,1,n)
    {
        C[i][0]=C[i][i]=1;
        FOR(j,1,i-1) C[i][j]=(C[i-1][j-1]+C[i-1][j])%mod;
    }
    f[0]=1; g[0]=0;
    FOR(i,1,m)
    {
        FOR(j,1,i)
        {
            s=(j*(j-1)/2+(i-j+1)*(i-j)/2)%mod;
            ADD(f[i],f[j-1]*f[i-j]%mod*(i+1)%mod*C[i-1][j-1]);
            ADD(g[i],((g[j-1]*f[i-j]+f[j-1]*g[i-j])%mod*(i+1)+f[j-1]*f[i-j]%mod*s)%mod*C[i-1][j-1]);
        }
    }
    h[0][0][0]=1;
    FOR(i,0,min(m,n-m+1)-1)
    {
        FOR(j,0,m-1)
        {
            FOR(k,1,m-j)
            {
                F=f[k]*C[j+k][j]%mod;
                ADD(h[i+1][j+k][0],h[i][j][0]*F);
                ADD(h[i+1][j+k][1],h[i][j][1]*F);
                ADD(h[i+1][j+k][1],h[i][j][0]*g[k]%mod*C[j+k][j]);
            }
        }
    }
    for(i=1; i<=min(m,n-m+1); i++) ADD(ans,h[i][m][1]*C[n-m+1][i]);
    std::cout << (ans+mod)%mod << std::endl;
    return 0;
}
